import React, { useEffect, useCallback } from 'react'
import { Modal, Button } from 'antd'
import ModalWrapper from './index.style'
import OTPInput from '../OtpInput'
import IntlMessages from '../../../../../../components/utility/intlMessages'
import { useCountdown } from './useCount'

const OtpModal = ({ isOpen, closeModal, operationId, otpInputMessage, verifyOtpRequest, loading, otpInputError, triggerChange, resendOtpRequest, resendLoader }) => {
  const [countDown, resetCountdown] = useCountdown()

  useEffect(() => {
    resetCountdown()
    // eslint-disable-next-line
  }, [isOpen])

  const handleSubmit = useCallback((val, operationId) => {
    if (operationId) {
      verifyOtpRequest({
        body: {
          otp: val,
          operation_id: operationId
        }
      })
    } else {
      console.log('Operation not found', operationId)
    }
    // eslint-disable-next-line
  }, [])

  const handleResendRequest = useCallback(() => {
    resendOtpRequest()
    // eslint-disable-next-line
  }, [])

  return (
    <Modal title='' visible={isOpen} onCancel={closeModal} footer={null}>
      <ModalWrapper>
        <div className='modal'>
          <div className='modal-header'>
            <img
              src='https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/policies/shopee/verification-icon.svg'
              alt='Images'
            />
          </div>

          <div className='modal-body'>
            <h2>
              <IntlMessages id='Verifikasi OTP' />
            </h2>
            <p>
              <IntlMessages id='Silahkan masukan nomor OTP yang telah dikirimkan ke email Anda' /><br />
              <small className='modal-small-text'><IntlMessages id='Silakan periksa email spam Anda, jika Anda tidak menerimanya di kotak masuk Anda' /></small>
            </p>
            <section className='otpSection'>
              <OTPInput onSubmit={handleSubmit} isError={otpInputError} triggerChange={triggerChange} operationId={operationId} isOpen={isOpen} />
              {otpInputMessage.length && otpInputError ? <div className='otpError'><IntlMessages id={otpInputMessage} /></div> : null}
            </section>

            <section className='resend-container'>
              {countDown !== 0 ? (
                <p>
                  <IntlMessages id='Kirim ulang OTP dalam' /> {countDown} s{' '}
                </p>
              ) : (
                <div className='resend-btn'>
                  <Button loading={resendLoader} onClick={handleResendRequest}><IntlMessages id='Kirim ulang OTP' /></Button>
                </div>
              )}
            </section>
          </div>

          <div className='resend-footer'>
            <Button loading={loading} onClick={handleSubmit}><IntlMessages id='Memeriksa' /></Button>
          </div>
        </div>
      </ModalWrapper>
    </Modal>
  )
}

export default OtpModal
