import React, { Component } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, Button, Alert, notification, Modal, Collapse } from 'antd'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import queryString from 'query-string'
import {
  ContainerLayout,
  CustomButton,
  FlexContainer,
  ModalContainer
} from './index.style'
import { modalContentBaseUrl, modalContent } from '../constants'
import validator from '../../../../../helpers/validator'
import { get } from 'lodash'
import { getFormItems } from '../../../../../components/utility/formItems'
import ThaiElectronicEndorseWelcome from '../ThaiElectronicThankYou'
import { ERROR_STRINGS } from '../../../../../constants/lang'
import moment from 'moment'
import OtpModal from './OtpModal'
import SuccessModal from './OtpModal/SuccessModal'
const { Panel } = Collapse

const {
  resetReduxPolicy,
  tokenizedDetailEndorsement,
  authorisedEndorsement,
  sendOtp,
  verifyOtp,
  resendOtp
} = policyAction

class FormContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      internalID: '',
      token: '',
      serielNoModel: false,
      otpModal: false,
      successModal: false,
      verifiedEmail: false,
      operationId: '',
      otpInputError: false,
      otpInputErrorMessage: '',
      btnDisable: false
    }
  }

  componentDidMount () {
    const { id } = this.props
    const internalId = get(id, 'match.params.id')
    const tokenObject = get(id, 'location.search', '')
    if (tokenObject) {
      const token = get(queryString.parse(tokenObject), 'token', '')
      if (token && internalId) {
        this.setState({
          internalId: internalId,
          token: token
        })
        this.props.tokenizedDetailEndorsement({
          query: {
            id: internalId,
            token: token
          }
        })
      }
    }

    if (!this.state.btnDisable) {
      this.setState({ btnDisable: true })
    }
  }

  componentWillReceiveProps (nextProps) {
    const {
      policyEndorsementError,
      policyEndorsement,
      policyEndorsementMessage,
      sendOtpData,
      sendOtpMessage,
      verifyOtpMessage,
      verifyOtpData,
      type,
      resendOtpData,
      resendOtpMessage
    } = nextProps
    if (
      policyEndorsementMessage !== '' &&
      policyEndorsementMessage !== 'success'
    ) {
      const errorData = get(policyEndorsement, 'error', '')
      if (!policyEndorsementError && errorData && errorData !== 'success') {
        if (Array.isArray(errorData)) {
          errorData.forEach((item) => {
            if (get(item, 'key', '')) {
              if (item.key === 'serial_number') {
                if (type === 'crack-screen') {
                  this.props.form.setFields({
                    [item.key]: {
                      value: item.val,
                      errors: [
                        new Error(
                          this.intlText({
                            id: 'Nomor IMEI sudah memiliki polis aktif'
                          })
                        )
                      ]
                    }
                  })
                }
                if (type === 'full-gadget') {
                  this.props.form.setFields({
                    [item.key]: {
                      value: item.val,
                      errors: [
                        new Error(
                          this.intlText({
                            id: 'Nomor sudah memiliki polis aktif'
                          })
                        )
                      ]
                    }
                  })
                }
              } else {
                this.props.form.setFields({
                  [item.key]: {
                    value: item.val,
                    errors: [new Error(this.intlText({ id: item.err }))]
                  }
                })
              }
            } else {
              notification['error']({
                message: this.intlText({ id: 'Error' }),
                description: this.intlText({ id: item.err })
              })
            }
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        } else {
          notification['error']({
            message: this.intlText({ id: 'Error' }),
            description: this.intlText({ id: errorData })
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        }
      }
    }

    if (sendOtpData !== undefined && sendOtpMessage === 'success') {
      const { operation_id: operationId = '' } = sendOtpData
      this.setState({ operationId: operationId, otpModal: true })
      this.props.resetReduxPolicy(['sendOtpMessage'])
      this.props.resetReduxPolicy(['sendOtpData'])
    } else if (sendOtpData !== undefined && sendOtpMessage === 'error') {
      const { error = '', message = '', result = '' } = sendOtpData
      const errorMessage = error || message || result || 'Gagal mengirim OTP'

      notification.error({
        message: this.intlText({ id: errorMessage })
      })
      this.props.resetReduxPolicy(['sendOtpMessage'])
      this.props.resetReduxPolicy(['sendOtpData'])
    }

    if (verifyOtpData !== undefined && verifyOtpMessage === 'success') {
      this.setState({ otpModal: false, successModal: true, verifiedEmail: true })

      this.props.resetReduxPolicy(['verifyOtpMessage'])
      this.props.resetReduxPolicy(['verifyOtpData'])
    } else if (verifyOtpData !== undefined && verifyOtpMessage === 'error') {
      const { error = '', message = '' } = verifyOtpData
      this.setState({ otpInputError: true, otpInputErrorMessage: error || message || 'Gagal Memverifikasi OTP' })
      this.props.resetReduxPolicy(['verifyOtpMessage'])
      this.props.resetReduxPolicy(['verifyOtpData'])
    }

    if (resendOtpData !== undefined && resendOtpMessage === 'success') {
      this.setState({ otpModal: true, successModal: false })
      notification.success({
        message: 'success'
      })
      this.props.resetReduxPolicy(['resendOtpMessage'])
      this.props.resetReduxPolicy(['resendOtpData'])
    } else if (resendOtpData !== undefined && resendOtpMessage === 'error') {
      const { error = '', message = '' } = resendOtpData
      notification.error({
        message: this.intlText({
          id: error || message || 'Gagal Mengirim Ulang Otp'
        })
      })

      this.props.resetReduxPolicy(['resendOtpMessage'])
      this.props.resetReduxPolicy(['resendOtpData'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  };

  triggerChange = () => {
    this.setState({
      otpInputError: false,
      otpInputErrorMessage: ''
    })
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  showErrorMessage = () => {
    return (
      <Alert
        message={<IntlMessages id={ERROR_STRINGS.error} />}
        description={<IntlMessages id={ERROR_STRINGS.serverError} />}
        type='error'
      />
    )
  };

  finalSubmit = async (e, userEmail) => {
    e.preventDefault()

    const { internalId, token } = this.state
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()

    if (!this.state.verifiedEmail && !userEmail) {
      notification.error({
        message: this.intlText({
          id: 'mohon verifikasi email anda terlebih dahulu'
        })
      })
      return
    }

    const payload = {
      ...formBody,
      dob: moment(formBody.dob).format('YYYY-MM-DD')
    }
    this.props.authorisedEndorsement({
      query: {
        internal_id: internalId,
        token: token
      },
      body: payload
    })
  };

  handleModelOpen = () => {
    this.setState({ serielNoModel: true })
  };

  handleModelClose = () => {
    this.setState({ serielNoModel: false })
  };

  handleVerifyModalOpen = (val) => {
    if (this.props.form.getFieldValue('email') === val) {
      this.setState({ btnDisable: false })
      return
    }
    if (this.state.verifiedEmail) {
      this.setState({ verifiedEmail: false })
      return
    }

    this.props.sendOtp({
      body: {
        type: 'email',
        email: this.props.form.getFieldValue('email'),
        partner: 'pasarpolis',
        template_code: 'shopeeth-send-otp'
      }
    })
  }

  handleResendRequest = () => {
    this.setState({ otpModal: true })
    this.props.resendOtp({
      body: {
        type: 'email',
        email: this.props.form.getFieldValue('email'),
        partner: 'pasarpolis',
        operation_id: this.state.operationId,
        medium: 'email',
        template_code: 'shopeeth-send-otp'
      }
    })
  }

  render () {
    const {
      getPolicyEndorsementDetailResult,
      policyEndorsementDetailLoading,
      policyEndorsementDetailError,
      policyEndorsementLoading,
      policyEndorsementMessage,
      header,
      subheading,

      sendOtpDataLoading,
      verifyOtpDataLoading
    } = this.props

    const isSuccessFulEndorse = (policyEndorsementMessage === 'success') || get(getPolicyEndorsementDetailResult, 'EndorsementStatus') === 'SUCCESS'
    const userEmail = get(getPolicyEndorsementDetailResult, 'Email', '')

    const inputLabel = 'Nama Lengkap (sesuai KTP Anda)'
    let secondInputHeading = 'Nomor Serial'

    const emailBtnTxt = this.state.verifiedEmail ? 'ganti email' : 'verifikasi email'
    let emailwarning =
      this.props.form.getFieldValue('email') === userEmail &&
      this.props.form.getFieldValue('email') && userEmail
        ? 'Email ini adalah akun email Shopee Anda.'
        : 'Silahkan masukan email aktif anda.'

    emailwarning = this.state.verifiedEmail ? 'Email Anda telah diverifikasi' : emailwarning

    return (
      <ContainerLayout>
        {isSuccessFulEndorse ? (
          <ThaiElectronicEndorseWelcome userEmail={userEmail} />
        ) : policyEndorsementDetailError ? (
          this.showErrorMessage()
        ) : (
          <CircularLoader
            isSpining={
              policyEndorsementDetailLoading || policyEndorsementLoading
            }
          >
            <FlexContainer>
              <Form onSubmit={(e) => this.finalSubmit(e, userEmail)}>
                <Row type='flex' align='middle'>
                  <Col
                    xs={24}
                    sm={24}
                    md={12}
                    lg={12}
                    xl={12}
                    className='padding-24'
                  >
                    <img
                      src='https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/policies/shopee/shopee-gadget-endorsement-image.png'
                      alt='shopeethai-electronic-banner'
                      width='100%'
                    />
                  </Col>
                  <Col
                    xs={24}
                    sm={24}
                    md={12}
                    lg={12}
                    xl={12}
                    className='padding-24'
                  >
                    <Row type='flex'>
                      <Col span={24}>
                        <h3 className='form-heading'>
                          <b>
                            <IntlMessages id={header} />
                          </b>
                        </h3>
                        <p className='form-subheading'>
                          <IntlMessages id={subheading} />
                        </p>
                      </Col>
                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'name',
                            type: 'alphanumericFloating',
                            label: inputLabel,
                            required: true,
                            validator: validator.checkValidator
                          })}
                        </Form.Item>
                      </Col>

                      <Col span={24} />

                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'dob',
                            type: 'date',
                            label: 'Tanggal lahir',
                            required: true,
                            validator: validator.checkDobShopee
                          })}
                        </Form.Item>
                      </Col>

                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'email',
                            type: 'verifyemail',
                            label: 'Email',
                            required: true,
                            btnText: emailBtnTxt,
                            btnLoading: !!sendOtpDataLoading,
                            verifiedEmail: this.state.verifiedEmail,
                            initialValue: userEmail,
                            emailwarning: emailwarning,
                            disableField: this.state.verifiedEmail || !!userEmail
                          })}
                        </Form.Item>
                      </Col>

                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'identity_no',
                            type: 'number',
                            label: 'No ID Nasional',
                            required: true,
                            validator: validator.nationalIdValidator
                          })}
                        </Form.Item>
                      </Col>

                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'serial_number',
                            type: 'alphanumericRestrict',
                            label: secondInputHeading,
                            required: true,
                            validator: validator.serialNumberValidator
                          })}
                        </Form.Item>
                      </Col>

                      <Col span={24}>
                        <p>
                          <IntlMessages id='*Masukkan Serial number untuk produk' />
                          <br />
                          <span
                            onClick={this.handleModelOpen}
                            className='theme-color link'
                          >
                            <IntlMessages id='Lihat Cara Menemukan Nomor Seri' />
                          </span>
                        </p>
                      </Col>
                      <Col span={24}>
                        <CustomButton
                          className='theme-button'
                          htmlType='submit'
                        >
                          <IntlMessages id={'Kirim'} />
                        </CustomButton>
                      </Col>
                    </Row>
                  </Col>
                </Row>
              </Form>
            </FlexContainer>
            <Modal
              title={this.intlText({ id: 'Panduan Menemukan Nomor Serial' })}
              visible={this.state.serielNoModel}
              onOk={this.handleModelClose}
              onCancel={this.handleModelClose}
              footer={null}
              centered
              wrapClassName='shopee-gadget-model'
            >
              <ModalContainer>
                <h4 className='modal-heading'>
                  <IntlMessages id='Serial Number berlaku untuk produk selain HP/Smartphone.' />
                </h4>
                <p>
                  <IntlMessages id='Pilih panduan produk di bawah ini untuk menemukan nomor seri produk Anda' />
                </p>

                <div className='content-area'>
                  {modalContent.map((content) => (
                    <Collapse bordered={false} expandIconPosition='right'>
                      <Panel
                        header={this.intlText({ id: content.title })}
                        key={content.key}
                      >
                        <img
                          src={`${modalContentBaseUrl}-${content.url}.png`}
                          alt={content.url}
                          width='100%'
                        />
                      </Panel>
                    </Collapse>
                  ))}
                </div>

                <div className='modal-back'>
                  <Button
                    className='action-button'
                    onClick={this.handleModelClose}
                  >
                    <IntlMessages id='Kembali' />
                  </Button>
                </div>
              </ModalContainer>
            </Modal>

            <OtpModal
              isOpen={this.state.otpModal}
              closeModal={() => this.setState({ otpModal: false })}
              operationId={this.state.operationId}
              otpInputMessage={this.state.otpInputErrorMessage}
              verifyOtpRequest={this.props.verifyOtp}
              loading={!!verifyOtpDataLoading}
              otpInputError={this.state.otpInputError}
              triggerChange={this.triggerChange}
              resendOtpRequest={this.handleResendRequest}
              resendLoader={!!this.props.resendOtpDataLoading}
            />

            <SuccessModal
              isOpen={this.state.successModal}
              closeModal={() => this.setState({ successModal: false })}
            />
          </CircularLoader>
        )}
      </ContainerLayout>
    )
  }
}

FormContainer.defaultProps = {
  policyEndorsementLoading: false,
  policyEndorsementError: false,
  policyEndorsementDetailLoading: false,
  policyEndorsementDetailError: false
}
const ShopeeEndorsementWrapped = Form.create()(FormContainer)
export default connect(
  (state) => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage: state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.AUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.AUTHORIZED_ENDORSEMENT,

    sendOtpData: state.Policy.sendOtpData,
    sendOtpMessage: state.Policy.sendOtpMessage,
    sendOtpDataLoading: state.Loading.SEND_VERIFICATION_OTP,

    resendOtpData: state.Policy.resendOtpData,
    resendOtpMessage: state.Policy.resendOtpMessage,
    resendOtpDataLoading: state.Loading.RESEND_VERIFICATION_OTP,

    verifyOtpData: state.Policy.verifyOtpData,
    verifyOtpMessage: state.Policy.verifyOtpMessage,
    verifyOtpDataLoading: state.Loading.VERIFY_VERIFICATION_OTP
  }),
  {
    resetReduxPolicy,
    tokenizedDetailEndorsement,
    authorisedEndorsement,
    sendOtp,
    verifyOtp,
    resendOtp
  }
)(injectIntl(ShopeeEndorsementWrapped))
