import React from 'react'
import { Input } from 'antd'
import { injectIntl } from 'react-intl'

class NumericInput extends React.Component {
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  onChange = e => {
    const { value } = e.target
    const { type } = this.props
    let reg = ''
    if (type === 'otp') {
      reg = /^-?(0|[0-9][0-9]*)(\.[0-9]*)?$/
    } else {
      reg = /^-?([1-9][0-9]*)(\.[0-9]*)?$/
    }
    if ((!isNaN(value) && reg.test(value)) || value === '') {
      this.props.onChange(value)
    }
  }

  render () {
    const { disabled, placeholderText } = this.props
    return (
      <Input
        {...this.props}
        onChange={this.onChange}
        disabled={disabled}
        placeholder={this.intlText({ id: placeholderText || ' ' })}
      />
    )
  }
}

export default injectIntl(NumericInput)
